-- RutasEC production-oriented schema v1. No live migration or payment processing.
-- Apply to a NEW D1 database; preserve the existing R2 demo ledger.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT UNIQUE, phone TEXT UNIQUE, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS operators(id TEXT PRIMARY KEY, legal_name TEXT NOT NULL, display_name TEXT NOT NULL, tax_id TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','suspended')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT NOT NULL REFERENCES users(id),operator_id TEXT NOT NULL REFERENCES operators(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','dispatcher','driver')),PRIMARY KEY(user_id,operator_id));
CREATE TABLE IF NOT EXISTS vehicles(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),type TEXT NOT NULL CHECK(type IN ('auto','suv','van','minivan','other')),model TEXT,plate TEXT,capacity INTEGER NOT NULL CHECK(capacity>0),status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_vehicles_operator ON vehicles(operator_id);
CREATE TABLE IF NOT EXISTS route_offers(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),origin TEXT NOT NULL,destination TEXT NOT NULL,service_type TEXT NOT NULL CHECK(service_type IN ('shared','private_fixed')),vehicle_type TEXT,price_cents INTEGER NOT NULL CHECK(price_cents>=0),currency TEXT NOT NULL DEFAULT 'USD',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_route_offers_search ON route_offers(service_type,origin,destination,active);
CREATE TABLE IF NOT EXISTS departures(id TEXT PRIMARY KEY,offer_id TEXT NOT NULL REFERENCES route_offers(id),vehicle_id TEXT NOT NULL REFERENCES vehicles(id),depart_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published','boarding','running','completed','cancelled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_departures_offer_time ON departures(offer_id,depart_at);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,customer_id TEXT REFERENCES users(id),offer_id TEXT NOT NULL REFERENCES route_offers(id),departure_id TEXT REFERENCES departures(id),mode TEXT NOT NULL CHECK(mode IN ('shared','private_fixed')),service_at TEXT,passenger_count INTEGER NOT NULL CHECK(passenger_count>0),amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL DEFAULT 'payment_pending' CHECK(status IN ('payment_pending','confirmed','cancelled','refunded','expired')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,confirmed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_bookings_customer ON bookings(customer_id,created_at);
CREATE INDEX IF NOT EXISTS idx_bookings_departure ON bookings(departure_id,status);
-- One seat may have only one ACTIVE claim per departure. Holds are not confirmed sales.
CREATE TABLE IF NOT EXISTS seat_claims(id TEXT PRIMARY KEY,departure_id TEXT NOT NULL REFERENCES departures(id),booking_id TEXT NOT NULL REFERENCES bookings(id),seat_number INTEGER NOT NULL CHECK(seat_number>0),status TEXT NOT NULL CHECK(status IN ('held','confirmed','released')),hold_expires_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_active_seat_per_departure ON seat_claims(departure_id,seat_number) WHERE status IN ('held','confirmed');
CREATE INDEX IF NOT EXISTS idx_seat_claims_booking ON seat_claims(booking_id);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),provider TEXT NOT NULL,provider_payment_id TEXT,method TEXT NOT NULL CHECK(method IN ('card','deuna','bank_transfer','other')),amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL DEFAULT 'initiated' CHECK(status IN ('initiated','pending','paid','failed','refunded')),idempotency_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT,UNIQUE(provider,provider_payment_id));
CREATE INDEX IF NOT EXISTS idx_payments_booking ON payments(booking_id,status);
CREATE TABLE IF NOT EXISTS payment_events(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES payments(id),provider_event_id TEXT,kind TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(payment_id,provider_event_id));
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),period_start TEXT NOT NULL,period_end TEXT NOT NULL,gross_cents INTEGER NOT NULL DEFAULT 0,platform_fee_cents INTEGER NOT NULL DEFAULT 0,processor_fee_cents INTEGER NOT NULL DEFAULT 0,net_cents INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','paid','void')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settlement_items(settlement_id TEXT NOT NULL REFERENCES settlements(id),payment_id TEXT NOT NULL REFERENCES payments(id),PRIMARY KEY(settlement_id,payment_id),UNIQUE(payment_id));
CREATE TABLE IF NOT EXISTS private_requests(id TEXT PRIMARY KEY,customer_id TEXT REFERENCES users(id),origin TEXT NOT NULL,destination TEXT NOT NULL,requested_at TEXT,details TEXT,status TEXT NOT NULL DEFAULT 'requested',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,actor_user_id TEXT REFERENCES users(id),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,details_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_events(entity_type,entity_id,created_at);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0001_initial');
